# Texts of the installer and the launcher in the 12 languages of the game (the same set and order as the co-op lobby in the game, native\lobby_text.c).
# One source for both: the installer reads it from its own folder, the launcher from <game>\coop\coop-texts.ps1.
# '||' in a text = a line break; {0} {1} = arguments of L. Keys not translated fall back to English.
# Language codes: en fr it de es ru pl pt-br (Brazil) ja ko zh-cn (simplified) zh-tw (traditional). Windows in Portuguese (Portugal) gets pt-br, in a language the game does not have: English.
$script:LANGS = [ordered]@{ "en" = "English"; "fr" = "Français"; "it" = "Italiano"; "de" = "Deutsch"; "es" = "Español"; "ru" = "Русский";
                            "pl" = "Polski"; "pt-br" = "Português (Brasil)"; "ja" = "日本語"; "ko" = "한국어"; "zh-cn" = "简体中文"; "zh-tw" = "繁體中文" }

# Windows' language (the UI language, then the format language) as one of the codes above; -Lang wins (also the game's own names: eng fre ita ger spa rus pol ptB jpn kor chS chT).
function Pick-Lang([string] $want) {
    $alias = @{ "eng" = "en"; "fre" = "fr"; "ita" = "it"; "ger" = "de"; "spa" = "es"; "rus" = "ru"; "pol" = "pl"; "ptb" = "pt-br"; "por" = "pt-br"; "jpn" = "ja"; "kor" = "ko"; "chs" = "zh-cn"; "cht" = "zh-tw" }
    $cands = @()
    if ($want) { $cands += $want.ToLower() } else { $cands += (Get-UICulture).Name.ToLower(); $cands += (Get-Culture).Name.ToLower() }
    foreach ($c in $cands) {
        if ($alias.ContainsKey($c)) { return $alias[$c] }
        if ($script:LANGS.Contains($c)) { return $c }
        if ($c -match '^zh') { if ($c -match 'tw|hk|mo|hant') { return "zh-tw" } else { return "zh-cn" } }
        if ($c -match '^pt') { return "pt-br" }
        $two = $c.Split('-')[0]
        if ($script:LANGS.Contains($two)) { return $two }
    }
    "en"
}

function L($key) {
    $text = $script:TEXTS[$script:lang][$key]
    if (-not $text) { $text = $script:TEXTS.en[$key] }
    if (-not $text) { return $key }
    $text = $text.Replace("||", "`n")
    if ($args.Count) { return ($text -f $args) }
    $text
}

